// TAT engine tests. Run: npm test
//
// Every expected value below was worked out by hand from the rules in
// docs/TAT.md (10:00-18:00 IST, Mon-Sat, 3h response, 24h = 3 working days
// resolution) -- NOT generated by running the code. If one fails, decide
// whether the code or the expectation is wrong before changing either.
//
// Calendar used throughout (October 2026):
//   Fri 09 · Sat 10 · Sun 11 · Mon 12 · Tue 13 · Wed 14 · Thu 15 · Fri 16
//   Sat 17 · Sun 18 · Mon 19 · Tue 20 · Wed 21 · Thu 22

import { test, describe } from "node:test";
import assert from "node:assert/strict";
import {
  clockStart,
  addWorkingMinutes,
  workingMinutesBetween,
  evaluateTicket,
  localDateKey,
  bucketKeyForDate,
  bucketsInRange,
  buildTatReport,
  TAT_CONFIG,
} from "../src/services/tat.js";

// "2026-10-12 10:00" (IST wall clock) -> Date
const ist = (s) => new Date(`${s.replace(" ", "T")}:00+05:30`);
const eqTime = (actual, expectedIst, msg) =>
  assert.equal(actual.toISOString(), ist(expectedIst).toISOString(), msg);

const R = TAT_CONFIG.responseTatMinutes;
const RES = TAT_CONFIG.resolutionTatMinutes;

describe("config", () => {
  test("response 3 working hours, resolution 24 working hours, 10:00-18:00 Mon-Sat", () => {
    assert.equal(R, 180);
    assert.equal(RES, 1440);
    assert.equal(TAT_CONFIG.workStartMinute, 600);
    assert.equal(TAT_CONFIG.workEndMinute, 1080);
    assert.deepEqual([...TAT_CONFIG.workDays], [1, 2, 3, 4, 5, 6]);
  });
});

describe("received inside working hours", () => {
  const cases = [
    // [received, clock start, response due, resolution due, label]
    ["2026-10-12 10:00", "2026-10-12 10:00", "2026-10-12 13:00", "2026-10-14 18:00", "R1 Mon 10:00 opening minute"],
    ["2026-10-12 11:30", "2026-10-12 11:30", "2026-10-12 14:30", "2026-10-15 11:30", "R2 Mon 11:30 mid-morning"],
    ["2026-10-12 16:00", "2026-10-12 16:00", "2026-10-13 11:00", "2026-10-15 16:00", "R3 Mon 16:00 response spills to next day"],
    ["2026-10-12 17:59", "2026-10-12 17:59", "2026-10-13 12:59", "2026-10-15 17:59", "R4 Mon 17:59 last working minute"],
    ["2026-10-12 15:00", "2026-10-12 15:00", "2026-10-12 18:00", "2026-10-15 15:00", "R5 Mon 15:00 deadline lands exactly on 18:00"],
  ];
  for (const [received, start, respDue, resDue, label] of cases) {
    test(label, () => {
      const e = evaluateTicket({ receivedAt: ist(received) }, ist(received));
      eqTime(e.clockStartAt, start, "clock start");
      eqTime(e.responseDueAt, respDue, "response due");
      eqTime(e.resolutionDueAt, resDue, "resolution due");
      assert.equal(e.afterHours, false);
    });
  }
});

describe("received outside working hours", () => {
  const cases = [
    ["2026-10-12 18:00", "2026-10-13 10:00", "2026-10-13 13:00", "2026-10-15 18:00", "R6 Mon 18:00 exactly counts as after-hours"],
    ["2026-10-12 21:00", "2026-10-13 10:00", "2026-10-13 13:00", "2026-10-15 18:00", "R7 Mon 21:00 evening"],
    ["2026-10-13 08:00", "2026-10-13 10:00", "2026-10-13 13:00", "2026-10-15 18:00", "R8 Tue 08:00 before opening, same day"],
    ["2026-10-13 00:00", "2026-10-13 10:00", "2026-10-13 13:00", "2026-10-15 18:00", "R9 Tue 00:00 midnight"],
    ["2026-10-12 09:59", "2026-10-12 10:00", "2026-10-12 13:00", "2026-10-14 18:00", "R9b Mon 09:59 one minute before opening"],
  ];
  for (const [received, start, respDue, resDue, label] of cases) {
    test(label, () => {
      const e = evaluateTicket({ receivedAt: ist(received) }, ist(received));
      eqTime(e.clockStartAt, start, "clock start");
      eqTime(e.responseDueAt, respDue, "response due");
      eqTime(e.resolutionDueAt, resDue, "resolution due");
      assert.equal(e.afterHours, true);
    });
  }
});

describe("weekends (Saturday works, Sunday off)", () => {
  test("R10 Sat 16:00 -- Saturday is a working day; response skips Sunday", () => {
    const e = evaluateTicket({ receivedAt: ist("2026-10-17 16:00") }, ist("2026-10-17 16:00"));
    assert.equal(e.afterHours, false);
    eqTime(e.responseDueAt, "2026-10-19 11:00"); // Sat 2h + Mon 1h
    eqTime(e.resolutionDueAt, "2026-10-21 16:00"); // Sat 2 + Mon 8 + Tue 8 + Wed 6
  });
  test("R11 Sat 18:30 -- clock starts Monday 10:00", () => {
    const e = evaluateTicket({ receivedAt: ist("2026-10-17 18:30") }, ist("2026-10-17 18:30"));
    assert.equal(e.afterHours, true);
    eqTime(e.clockStartAt, "2026-10-19 10:00");
    eqTime(e.responseDueAt, "2026-10-19 13:00");
  });
  test("R12 Sun 12:00 -- whole Sunday is after-hours", () => {
    const e = evaluateTicket({ receivedAt: ist("2026-10-18 12:00") }, ist("2026-10-18 12:00"));
    assert.equal(e.afterHours, true);
    eqTime(e.clockStartAt, "2026-10-19 10:00");
    eqTime(e.responseDueAt, "2026-10-19 13:00");
    eqTime(e.resolutionDueAt, "2026-10-21 18:00");
  });
  test("H5 Fri 10:00 -- resolution counts Saturday, skips Sunday", () => {
    const e = evaluateTicket({ receivedAt: ist("2026-10-16 10:00") }, ist("2026-10-16 10:00"));
    eqTime(e.resolutionDueAt, "2026-10-19 18:00"); // Fri 8 + Sat 8 + Mon 8
  });
});

describe("holidays", () => {
  test("H1 Sun 15:00, Monday holiday -- clock starts Tuesday", () => {
    const o = { holidays: ["2026-10-19"] };
    const e = evaluateTicket({ receivedAt: ist("2026-10-18 15:00") }, ist("2026-10-18 15:00"), o);
    eqTime(e.clockStartAt, "2026-10-20 10:00");
    eqTime(e.responseDueAt, "2026-10-20 13:00");
    eqTime(e.resolutionDueAt, "2026-10-22 18:00");
  });
  test("H2 received during working hours ON a holiday is after-hours", () => {
    const o = { holidays: ["2026-10-19"] };
    const e = evaluateTicket({ receivedAt: ist("2026-10-19 11:00") }, ist("2026-10-19 11:00"), o);
    assert.equal(e.afterHours, true);
    eqTime(e.clockStartAt, "2026-10-20 10:00");
  });
  test("H3 Fri 17:00, Saturday holiday -- skips Sat + Sun", () => {
    const o = { holidays: ["2026-10-17"] };
    const e = evaluateTicket({ receivedAt: ist("2026-10-16 17:00") }, ist("2026-10-16 17:00"), o);
    eqTime(e.responseDueAt, "2026-10-19 12:00"); // Fri 1h + Mon 2h
    eqTime(e.resolutionDueAt, "2026-10-21 17:00"); // Fri 1 + Mon 8 + Tue 8 + Wed 7
  });
  test("H4 Sat 17:00, Mon + Tue both holidays -- jumps to Wednesday", () => {
    const o = { holidays: ["2026-10-19", "2026-10-20"] };
    const e = evaluateTicket({ receivedAt: ist("2026-10-17 17:00") }, ist("2026-10-17 17:00"), o);
    eqTime(e.responseDueAt, "2026-10-21 12:00"); // Sat 1h + Wed 2h
  });
  test("holiday list accepts a Set too", () => {
    const o = { holidays: new Set(["2026-10-19"]) };
    eqTime(clockStart(ist("2026-10-18 15:00"), o), "2026-10-20 10:00");
  });
});

describe("timezone: everything is judged in IST, not UTC", () => {
  test("Z1 04:30 UTC = Mon 10:00 IST is inside working hours", () => {
    const e = evaluateTicket({ receivedAt: new Date("2026-10-12T04:30:00Z") }, new Date("2026-10-12T04:30:00Z"));
    assert.equal(e.afterHours, false);
    assert.equal(e.responseDueAt.toISOString(), "2026-10-12T07:30:00.000Z");
  });
  test("Z2 Sun 23:00 UTC = Mon 04:30 IST is a Monday, not a Sunday", () => {
    eqTime(clockStart(new Date("2026-10-11T23:00:00Z")), "2026-10-12 10:00");
  });
  test("Z3 12:45 UTC = Mon 18:15 IST is after-hours (looks like daytime in UTC)", () => {
    const e = evaluateTicket({ receivedAt: new Date("2026-10-12T12:45:00Z") }, new Date("2026-10-12T12:45:00Z"));
    assert.equal(e.afterHours, true);
    eqTime(e.clockStartAt, "2026-10-13 10:00");
  });
});

describe("status classification + boundaries (query Mon 10:00; response due 13:00; resolution due Wed 18:00)", () => {
  const q = { receivedAt: ist("2026-10-12 10:00") };
  const later = ist("2026-10-20 12:00");
  test("S1 reply at exactly the deadline is within TAT", () => {
    const e = evaluateTicket({ ...q, firstResponseAt: ist("2026-10-12 13:00") }, later);
    assert.equal(e.responseStatus, "met");
    assert.equal(e.responseBreached, false);
    assert.equal(e.responseWorkingMinutes, 180);
  });
  test("S2 reply one minute late is breached", () => {
    const e = evaluateTicket({ ...q, firstResponseAt: ist("2026-10-12 13:01") }, later);
    assert.equal(e.responseStatus, "late");
    assert.equal(e.responseBreached, true);
  });
  test("S3 reply one minute early is within TAT", () => {
    const e = evaluateTicket({ ...q, firstResponseAt: ist("2026-10-12 12:59") }, later);
    assert.equal(e.responseStatus, "met");
  });
  test("S4 no reply, deadline not reached -> pending, not breached", () => {
    const e = evaluateTicket(q, ist("2026-10-12 12:00"));
    assert.equal(e.responseStatus, "pending");
    assert.equal(e.responseBreached, false);
    assert.equal(e.responseWorkingMinutes, 120);
  });
  test("S5 no reply, now exactly at the deadline -> still pending", () => {
    assert.equal(evaluateTicket(q, ist("2026-10-12 13:00")).responseStatus, "pending");
  });
  test("S6 no reply, one minute past the deadline -> overdue (breached)", () => {
    const e = evaluateTicket(q, ist("2026-10-12 13:01"));
    assert.equal(e.responseStatus, "overdue");
    assert.equal(e.responseBreached, true);
  });
  test("S7 after-hours query answered before the clock even starts -> met, 0 working minutes", () => {
    const e = evaluateTicket(
      { receivedAt: ist("2026-10-12 21:00"), firstResponseAt: ist("2026-10-12 22:00") },
      later
    );
    assert.equal(e.responseStatus, "met");
    assert.equal(e.responseWorkingMinutes, 0);
  });
  test("S8a resolved exactly at the resolution deadline -> met", () => {
    const e = evaluateTicket({ ...q, resolvedAt: ist("2026-10-14 18:00") }, later);
    assert.equal(e.resolutionStatus, "met");
    assert.equal(e.resolutionWorkingMinutes, 1440);
  });
  test("S8b resolved at 18:01 after the deadline (overtime, no extra working time) -> late", () => {
    const e = evaluateTicket({ ...q, resolvedAt: ist("2026-10-14 18:01") }, later);
    assert.equal(e.resolutionStatus, "late");
    assert.equal(e.resolutionBreached, true);
    assert.equal(e.resolutionWorkingMinutes, 1440);
  });
  test("S9 unresolved past the resolution deadline -> overdue", () => {
    const e = evaluateTicket(q, ist("2026-10-15 10:00"));
    assert.equal(e.resolutionStatus, "overdue");
    assert.equal(e.resolutionBreached, true);
  });
  test("S10 unresolved within the resolution deadline -> pending", () => {
    assert.equal(evaluateTicket(q, ist("2026-10-14 17:00")).resolutionStatus, "pending");
  });
});

describe("working minutes elapsed", () => {
  test("W1 Mon 17:00 -> Tue 11:00 = 2h", () =>
    assert.equal(workingMinutesBetween(ist("2026-10-12 17:00"), ist("2026-10-13 11:00")), 120));
  test("W2 Mon 17:00 -> Tue 09:00 = 1h (overnight + early morning don't count)", () =>
    assert.equal(workingMinutesBetween(ist("2026-10-12 17:00"), ist("2026-10-13 09:00")), 60));
  test("W3 Sat 17:00 -> Mon 10:30 = 1h30 (Sunday doesn't count)", () =>
    assert.equal(workingMinutesBetween(ist("2026-10-17 17:00"), ist("2026-10-19 10:30")), 90));
  test("W4 Mon 21:00 -> Mon 22:00 = 0", () =>
    assert.equal(workingMinutesBetween(ist("2026-10-12 21:00"), ist("2026-10-12 22:00")), 0));
  test("W5 end before start = 0", () =>
    assert.equal(workingMinutesBetween(ist("2026-10-13 11:00"), ist("2026-10-12 11:00")), 0));
  test("addWorkingMinutes(0) from after-hours = next opening", () =>
    eqTime(addWorkingMinutes(ist("2026-10-12 20:00"), 0), "2026-10-13 10:00"));
});

describe("report buckets (IST dates)", () => {
  test("B1 20:00 UTC Mon = 01:30 IST Tue -> Tuesday's bucket", () =>
    assert.equal(localDateKey(new Date("2026-10-12T20:00:00Z")), "2026-10-13"));
  test("B2 weeks run Monday-Sunday", () => {
    assert.equal(bucketKeyForDate("2026-10-18", "week"), "2026-10-12"); // Sunday -> its Monday
    assert.equal(bucketKeyForDate("2026-10-12", "week"), "2026-10-12");
    assert.equal(bucketKeyForDate("2026-10-19", "week"), "2026-10-19");
  });
  test("B3 Oct 31 19:00 UTC = Nov 1 00:30 IST -> November", () =>
    assert.equal(bucketKeyForDate(localDateKey(new Date("2026-10-31T19:00:00Z")), "month"), "2026-11"));
  test("B4 two weekly buckets", () =>
    assert.deepEqual(bucketsInRange("2026-10-12", "2026-10-25", "week"), [
      { key: "2026-10-12", startKey: "2026-10-12", endKey: "2026-10-18" },
      { key: "2026-10-19", startKey: "2026-10-19", endKey: "2026-10-25" },
    ]));
  test("B5 monthly buckets cover whole months", () =>
    assert.deepEqual(bucketsInRange("2026-10-15", "2026-12-03", "month"), [
      { key: "2026-10", startKey: "2026-10-01", endKey: "2026-10-31" },
      { key: "2026-11", startKey: "2026-11-01", endKey: "2026-11-30" },
      { key: "2026-12", startKey: "2026-12-01", endKey: "2026-12-31" },
    ]));
});

describe("daily report, end to end (range Mon 12 - Wed 14, now = Wed 12:00)", () => {
  // A  Mon 11:00, replied Mon 12:00, resolved Tue 15:00            -> all within TAT
  // B  Mon 17:00, replied Tue 11:30 (due Tue 12:00), unresolved     -> response met
  // C  Mon 20:00 (after-hours), never replied (due Tue 13:00)       -> overdue
  // D  Tue 10:30, replied Tue 14:00 (due 13:30)                     -> late
  // E  Wed 11:00, not replied yet (due 14:00)                       -> pending
  // F  Fri 9 15:00 (before range), never replied                    -> in backlog only
  // G  Fri 9 16:00 (before range), replied Mon 10:30                -> not in Mon backlog
  const tickets = [
    { id: "A", receivedAt: ist("2026-10-12 11:00"), firstResponseAt: ist("2026-10-12 12:00"), resolvedAt: ist("2026-10-13 15:00") },
    { id: "B", receivedAt: ist("2026-10-12 17:00"), firstResponseAt: ist("2026-10-13 11:30") },
    { id: "C", receivedAt: ist("2026-10-12 20:00") },
    { id: "D", receivedAt: ist("2026-10-13 10:30"), firstResponseAt: ist("2026-10-13 14:00") },
    { id: "E", receivedAt: ist("2026-10-14 11:00") },
    { id: "F", receivedAt: ist("2026-10-09 15:00") },
    { id: "G", receivedAt: ist("2026-10-09 16:00"), firstResponseAt: ist("2026-10-12 10:30") },
  ];
  const report = buildTatReport({
    tickets,
    period: "day",
    fromKey: "2026-10-12",
    toKey: "2026-10-14",
    now: ist("2026-10-14 12:00"),
  });
  const [mon, tue, wed] = report.buckets;

  test("three daily buckets", () => assert.deepEqual(report.buckets.map((b) => b.key), ["2026-10-12", "2026-10-13", "2026-10-14"]));

  test("Monday", () => {
    assert.deepEqual(mon.ids.received, ["A", "B", "C"]);
    assert.deepEqual(mon.ids.respondedWithinTat, ["A", "B"]);
    assert.deepEqual(mon.ids.respondedLate, []);
    assert.deepEqual(mon.ids.awaitingResponse, ["C"]);
    assert.deepEqual(mon.ids.responseBreached, ["C"]);
    assert.deepEqual(mon.ids.resolvedWithinTat, ["A"]);
    assert.deepEqual(mon.ids.unresolved, ["B", "C"]);
    assert.deepEqual(mon.ids.resolutionBreached, []);
    assert.deepEqual(mon.ids.afterHours, ["C"]);
    assert.deepEqual(mon.ids.backlogAtClose, ["B", "F"]);
    eqTime(mon.backlogAsOf, "2026-10-12 18:00");
  });

  test("Tuesday", () => {
    assert.deepEqual(tue.ids.received, ["D"]);
    assert.deepEqual(tue.ids.respondedLate, ["D"]);
    assert.deepEqual(tue.ids.responseBreached, ["D"]);
    assert.deepEqual(tue.ids.unresolved, ["D"]);
    assert.deepEqual(tue.ids.backlogAtClose, ["C", "F"]);
    eqTime(tue.backlogAsOf, "2026-10-13 18:00");
  });

  test("Wednesday (today) backlog is as of now, not 18:00", () => {
    assert.deepEqual(wed.ids.received, ["E"]);
    assert.deepEqual(wed.ids.awaitingResponse, ["E"]);
    assert.deepEqual(wed.ids.responseBreached, []);
    assert.deepEqual(wed.ids.backlogAtClose, ["C", "E", "F"]);
    eqTime(wed.backlogAsOf, "2026-10-14 12:00");
  });

  test("totals cover only queries received in the range (not F, G)", () => {
    assert.deepEqual(report.totals, {
      received: 5,
      respondedWithinTat: 2,
      responseBreached: 2,
      awaitingResponse: 2,
      resolvedWithinTat: 1,
      resolutionBreached: 0,
      unresolved: 4,
    });
  });

  test("Sunday bucket has no backlog figure", () => {
    const r = buildTatReport({ tickets, period: "day", fromKey: "2026-10-18", toKey: "2026-10-18", now: ist("2026-10-20 12:00") });
    assert.equal(r.buckets[0].backlogAsOf, null);
    assert.deepEqual(r.buckets[0].ids.backlogAtClose, []);
  });
});
